fragment:




        @(String.Format("Staring authentication for request {0} of API: {1}", (string)context.Variables["soapAction"],(string)context.Variables["apiName"]))

    <set-variable name="hasUsernameToken" value="@{
            try
            {
            var xml = context.Request.Body.As
                    (preserveContent: true);
            return xml.Descendants().Any(e => e.Name.LocalName == "UsernameToken");
            }
            catch
            {
            return false;
            }
            }" />

            <when condition="@(context.Variables.GetValueOrDefault
                ("hasUsernameToken"))">


                    <set-variable name="soapBody" value="@{
return context.Request.Body.As
                        (preserveContent: true);
}" />


                            <when condition="@{
try {
var xml = new System.Xml.XmlDocument();
xml.LoadXml(context.Variables.GetValueOrDefault
                                ("soapBody"));
var node = xml.SelectSingleNode("//*[local-name()='Username']");
var node2 = xml.SelectSingleNode("//*[local-name()='Password']");
return false; // No error
} catch {
return true; // Error occurred
}
}">

                                        Authentication failed. Reason: Failed to parsing SOAP Header XML




                                            application/soap+xml; charset=utf-8


                                            <soap:Envelope xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><soap:Fault><faultcode>soap:Server</faultcode><faultstring>Error Access denied. Authentication failed.</faultstring></soap:Fault></soap:Body></soap:Envelope>





                            <set-variable name="username" value="@{
var xml = new System.Xml.XmlDocument();
xml.LoadXml(context.Variables.GetValueOrDefault
                                ("soapBody"));
var node = xml.SelectSingleNode("//*[local-name()='Username']");
return node != null ? node.InnerText : null;
}" />
                                <set-variable name="password" value="@{
var xml = new System.Xml.XmlDocument();
xml.LoadXml(context.Variables.GetValueOrDefault
                                    ("soapBody"));
var node = xml.SelectSingleNode("//*[local-name()='Password']");
return node != null ? node.InnerText : null;
}" />


                                        <when condition="@(string.IsNullOrEmpty((string)context.Variables.GetValueOrDefault
                                            ("username")) || string.IsNullOrEmpty((string)context.Variables.GetValueOrDefault
                                                ("password")))">

                                                        Authentication failed. Reason: Username or Password is Empty




                                                            application/soap+xml; charset=utf-8



<soap:Envelope xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><soap:Fault><faultcode>soap:Server</faultcode><faultstring>Error Access denied. Authentication failed.</faultstring></soap:Fault></soap:Body></soap:Envelope>








                                                @(String.Format("Trying to authenticate user: {0} with basic auth", (string)context.Variables["username"]))


                                                {{foc-b2c-basic-auth-token-url}}
                                                POST

                                                    application/x-www-form-urlencoded

                                                @{
return "client_id={{foc-b2c-proxy-api-client-id}}" +
"&grant_type=client_credentials" +
"&client_secret={{foc-b2c-proxy-api-client-secret}}" +
"&scope={{foc-b2c-client-scope}}";
}


                                            <set-variable name="access_token" value="@( ((IResponse)context.Variables["tokenResponse"]).Body.As
                                                ()["access_token"] )" />

                                                    {{foc-b2c-auth-proxy-api-url}}
                                                    POST

                                                        application/json


                                                        @($"Bearer {context.Variables["access_token"]}")


                                                        {{foc-b2c-proxy-api-subscription-key}}


                                                        @(Guid.NewGuid().ToString())


                                                        b2c-auth-policy


                                                        {{foc-az-apim-internal-routing-host}}


                                                        application/json


@{
return "{ \"username\": \"" + context.Variables["username"] + "\", \"password\": \"" + context.Variables["password"] + "\" }";
}






                                                            @(String.Format("Authentication failed. Reason : {0}",((IResponse)context.Variables["tokenValidationResponse"]).Body.As
                                                                () ))





                                                                    application/soap+xml; charset=utf-8


                                                                    <soap:Envelope xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><soap:Fault><faultcode>soap:Server</faultcode><faultstring>Error Access denied. Authentication failed.</faultstring></soap:Fault></soap:Body></soap:Envelope>





                                                            <set-variable name="tokenValidationBody" value="@((string)context.Variables.GetValueOrDefault
                                                                ("tokenValidationResponse")?.Body.As
                                                                    ())" />

                                                                    <set-variable name="userRoles" value="@{
var json = context.Variables.GetValueOrDefault
                                                                        ("tokenValidationBody");
if (string.IsNullOrEmpty(json)) {
return "";
}
var obj = Newtonsoft.Json.Linq.JObject.Parse(json);
var rolesArray = obj["roles"];
if (rolesArray == null) {
return "";
}
var rolesList = new List
                                                                            ();
foreach (var role in rolesArray) {
rolesList.Add((string)role);
}
return string.Join(",", rolesList);
}" />



                                                                        @(String.Format("User: {0} authenticated Successfully", (string)context.Variables["username"]))





                                                                        Trying to authenticate user with JWT auth





                                                                            @((string)context.Variables["audience"])


                                                                            @((string)context.Variables["issuer"])




                                                                    <set-variable name="jwtPayload" value="@{
var token = context.Variables.GetValueOrDefault
                                                                        ("jwtToken");
if (string.IsNullOrEmpty(token)) { return ""; }
var parts = token.Split('.');
if (parts.Length != 3) { return ""; }
var payload = parts[1];
switch (payload.Length % 4)
{
case 2: payload += "=="; break;
case 3: payload += "="; break;
}
var bytes = System.Convert.FromBase64String(payload.Replace('-', '+').Replace('_', '/'));
return System.Text.Encoding.UTF8.GetString(bytes);
}" />

                                                                        <set-variable name="clientId" value="@{
var json = context.Variables.GetValueOrDefault
                                                                            ("jwtPayload");
if (string.IsNullOrEmpty(json)) { return ""; }
var obj = Newtonsoft.Json.Linq.JObject.Parse(json);
var azp = obj["azp"];
return azp == null ? "" : (string)azp;
}" />

                                                                            <set-variable name="userRoles" value="@{
var json = context.Variables.GetValueOrDefault
                                                                                ("jwtPayload");
if (string.IsNullOrEmpty(json)) { return ""; }
var obj = Newtonsoft.Json.Linq.JObject.Parse(json);
var rolesArray = obj["roles"];
if (rolesArray == null) { return "adminrole-1"; }
var rolesList = new List
                                                                                    ();
foreach (var role in rolesArray) {
rolesList.Add((string)role);
}
return string.Join(",", rolesList);
}" />

                                                                                        @(String.Format("ClientId: {0} Authenticated Successfully", (string)context.Variables["clientId"]))




                                                                                        Authentication failed: Authorization header not supplied or not recognized





                                                                                            application/soap+xml; charset=utf-8


                                                                                            <soap:Envelope xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><soap:Fault><faultcode>soap:Server</faultcode><faultstring>Error Access denied. Authentication failed.</faultstring></soap:Fault></soap:Body></soap:Envelope>
